-- Identity set, 0000_init: the final squash (SH-12, program spec §2 "Final squash") of the stacked
-- history 0000_init .. 0010_outbox into one baseline. identity.squash.int-spec.ts proves it builds the
-- same catalog on Citus as the stacked files (kept in test/stacked-history).
-- Generated by drizzle-kit, then hand-edited into the sharding design's order (§4 items 2 and 6):
-- per table CREATE -> distribution -> indexes, the tables in distribution order (reference tables,
-- parents before children; then the tenant-distributed; then the user-distributed; the outbox last),
-- then the FKs, then RLS -> grants -> policies. One statement each: with local execution off, Citus
-- builds the shards over new connections.
-- Distribution (SH-5): users, tenants and memberships are reference tables (the global email and
-- slug uniques; policy helpers read memberships on every node); invitations, audit_events and the
-- outbox are distributed by tenant_id, colocated with app.tenant_colocation; sessions by user_id
-- (refresh routes by sub + jti). The platform helpers are no-ops without Citus and on a re-run.
-- Hand-edited to IF NOT EXISTS: the drizzle migrator creates this schema first, for identity.__drizzle_migrations.
CREATE SCHEMA IF NOT EXISTS "identity";
--> statement-breakpoint
CREATE TYPE "identity"."tenant_role" AS ENUM('owner', 'admin', 'member');--> statement-breakpoint
CREATE TABLE "identity"."users" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"email" text NOT NULL,
	"password_hash" text NOT NULL,
	"display_name" text NOT NULL,
	"is_platform_staff" boolean DEFAULT false NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "users_email_unique" UNIQUE("email")
);
--> statement-breakpoint
